#!/bin/bash
# Restyle the Limine boot menu: OLED black, synthwave palette, a 2 s menu.
# Run as your user; it asks for sudo.
#
#   ./install.sh                 apply the style to the global header of limine.conf
#   ./install.sh --uninstall     put the original header back
#
# Only the global header (everything above the first entry) is touched. The entries
# are regenerated by limine-entry-tool and limine-snapper-sync, which keep the header.
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
begin='### synthwave-84-oled begin (limine/install.sh)'
end='### synthwave-84-oled end'

if (( EUID == 0 )); then
  echo "Run as your user, not under sudo." >&2
  exit 1
fi

conf=${LIMINE_CONF:-}  # override for testing
[[ -n $conf ]] ||
for c in /boot/limine.conf /boot/EFI/limine/limine.conf /efi/limine.conf; do
  if sudo test -f "$c"; then conf=$c; break; fi
done
[[ -n $conf ]] || { echo "No limine.conf found." >&2; exit 1; }
orig=$conf.synthwave-original-header

t=$(mktemp -d); trap 'rm -rf "$t"' EXIT
sudo cat "$conf" > "$t/conf"
# Header = lines before the first entry ("/" at column 0).
n=$(grep -n -m1 '^/' "$t/conf" | cut -d: -f1 || true)
[[ -n $n ]] || { echo "$conf has no entries; refusing to touch it." >&2; exit 1; }
head -n $((n - 1)) "$t/conf" > "$t/header"
tail -n +"$n" "$t/conf" > "$t/body"

if [[ ${1:-} == --uninstall ]]; then
  if ! sudo test -f "$orig"; then
    echo "Not installed (no $orig)." >&2
    exit 1
  fi
  sudo cat "$orig" > "$t/new"
  cat "$t/body" >> "$t/new"
  sudo install -m700 "$t/new" "$conf"
  sudo rm -f "$orig"
  echo "Restored the original Limine header in $conf."
  exit 0
fi

# Keep the first original header we saw, so reinstalling never saves our own.
sudo test -f "$orig" || sudo install -m600 "$t/header" "$orig"
sudo install -m600 "$t/conf" "$conf.bak-synthwave-$(date +%Y%m%d%H%M%S)"

# Drop our old block, every key we set, and their commented-out or heading lines.
keys='timeout|quiet|interface_branding_colou?r|interface_help_colou?r(_bright)?|interface_help_hidden|backdrop|wallpaper|wallpaper_style|term_[a-z_]+'
awk -v b="$begin" -v e="$end" -v k="^#? *($keys):" '
  $0 == b { skip = 1; next }
  $0 == e { skip = 0; next }
  skip { next }
  $0 ~ k { next }
  /^# (Terminal|Text) colors/ { next }
  { print }
' "$t/header" | cat -s | sed -e :a -e '/^\n*$/{$d;N;ba' -e '}' > "$t/new"
{
  echo
  echo "$begin"
  cat "$here/header.conf"
  echo "$end"
  echo
  cat "$t/body"
} >> "$t/new"
sudo install -m700 "$t/new" "$conf"
echo "Styled the Limine menu in $conf (original header saved to $orig)."
